-- ---- the school: tracks, strands, sections and courses
SET @strand_BUSSENT = (SELECT id FROM strands WHERE code = 'BUSSENT'); SET @track_BUSSENT = (SELECT track_id FROM strands WHERE id = @strand_BUSSENT);
