SET @sec_BUSSENT_A = (SELECT s.id FROM sections s JOIN strands st ON st.id = s.strand_id JOIN schedules sc ON sc.id = s.schedule_id WHERE st.code = 'BUSSENT' AND sc.code = 'AM' AND s.name = 'A' AND s.grade_level = 11 AND s.school_year_id = @year LIMIT 1);
