-- ================================================================ 1) The enrollment of the students
INSERT INTO enrollments (id, school_year_id, term_id, section_id, student_id, lrn, first_name, middle_name, last_name, grade_level, track_id, strand_id, subjects, status, enrolled_by_user_id, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @e0 + 1 AS id, @year AS school_year_id, @term AS term_id, @sec_BUSSENT_A AS section_id, @s_1 AS student_id, '123456789012' AS lrn, 'Juan' AS first_name, 'Santos' AS middle_name, 'Dela Cruz' AS last_name, 11 AS grade_level, @track_BUSSENT AS track_id, @strand_BUSSENT AS strand_id, 'BUSINESS ACCOUNTING, ADVANCE MATHEMATICS 1, EFFECTIVE COMMUNICATION, MABISANG KOMUNIKASYON, GENERAL MATHEMATICS, LIFE AND CAREER SKILLS, GENERAL SCIENCE, PAG-AARAL NG KASAYSAYAN AT LIPUNANG PILIPINO' AS subjects, 'Enrolled' AS status, @u_registrar AS enrolled_by_user_id, (@day0 + INTERVAL -39 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -39 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @e0 + 2, @year, @term, @sec_BUSSENT_A, @s_2, '105202600001', 'Mariel', 'Aguilar', 'Abad', 11, @track_BUSSENT, @strand_BUSSENT, 'BUSINESS ACCOUNTING, ADVANCE MATHEMATICS 1, EFFECTIVE COMMUNICATION, MABISANG KOMUNIKASYON, GENERAL MATHEMATICS, LIFE AND CAREER SKILLS, GENERAL SCIENCE, PAG-AARAL NG KASAYSAYAN AT LIPUNANG PILIPINO', 'Enrolled', @u_registrar, (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @e0 + 3, @year, @term, @sec_BUSSENT_A, @s_3, '105202600002', 'Carlo', 'Bautista', 'Alcantara', 11, @track_BUSSENT, @strand_BUSSENT, 'BUSINESS ACCOUNTING, ADVANCE MATHEMATICS 1, EFFECTIVE COMMUNICATION, MABISANG KOMUNIKASYON, GENERAL MATHEMATICS, LIFE AND CAREER SKILLS, GENERAL SCIENCE, PAG-AARAL NG KASAYSAYAN AT LIPUNANG PILIPINO', 'Enrolled', @u_registrar, (@day0 + INTERVAL -37 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -37 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @e0 + 4, @year, @term, @sec_BUSSENT_A, @s_4, '105202600003', 'Jasmine', 'Cruz', 'Andrada', 11, @track_BUSSENT, @strand_BUSSENT, 'BUSINESS ACCOUNTING, ADVANCE MATHEMATICS 1, EFFECTIVE COMMUNICATION, MABISANG KOMUNIKASYON, GENERAL MATHEMATICS, LIFE AND CAREER SKILLS, GENERAL SCIENCE, PAG-AARAL NG KASAYSAYAN AT LIPUNANG PILIPINO', 'Enrolled', @u_registrar, (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
