  SELECT @ta0 + 1 AS id, @t_0 AS teacher_id, @sec_BUSSENT_A AS section_id, @sub_0 AS subject_id, (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @ta0 + 2, @t_1, @sec_BUSSENT_A, @sub_1, (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
