INSERT INTO system_settings (`key`, `value`, updated_at_utc, updated_by_user_id)
SELECT r.k, r.v, @now, @u_admin FROM (
  SELECT 'school.name' AS k, 'South East-Asia Institute of Trade and Technology' AS v
  UNION ALL SELECT 'school.short_name', 'SEAITT'
  UNION ALL SELECT 'school.tagline', 'Senior High School'
  UNION ALL SELECT 'school.address', 'Legazpi City, Albay'
  UNION ALL SELECT 'school.contact_email', 'admin@legazpi.seaitt.edu.ph'
  UNION ALL SELECT 'school.contact_phone', ''
  UNION ALL SELECT 'signin.max_failed_attempts', '5'
  UNION ALL SELECT 'signin.lockout_minutes', '15'
  UNION ALL SELECT 'maintenance.on', '0'
  UNION ALL SELECT 'maintenance.message', 'The system is being maintained. Please try again later.'
  UNION ALL SELECT 'messages.closing_hours', '1'
  UNION ALL SELECT 'messages.close_hour', '19'
  UNION ALL SELECT 'messages.open_hour', '7'
  UNION ALL SELECT 'backup.auto_on', '0'
  UNION ALL SELECT 'backup.auto_hour', '2'
  UNION ALL SELECT 'backup.keep', '7'
  UNION ALL SELECT 'logs.keep_days', '180'
  UNION ALL SELECT 'files.max_mb', '10'
  UNION ALL SELECT 'files.locker_mb', '100'
) AS r WHERE NOT EXISTS (SELECT 1 FROM system_settings x WHERE x.`key` = r.k) AND @u_admin IS NOT NULL;

-- the sample people have signed in recently
UPDATE users SET last_login_at_utc = DATE_SUB(@now, INTERVAL MOD(id, 70) + 1 HOUR) WHERE id > 0 AND role_id IN (2, 3, 4, 5, 6, 7) AND last_login_at_utc IS NULL AND email LIKE '%@legazpi.seaitt.edu.ph' AND @go = 1;

-- ================================================================ 10) A teacher evaluation: sent to two sections, answered by most of the students
INSERT INTO teacher_evaluations (id, title, instructions, sent_at_utc, due_at_utc, term_id, created_by_user_id, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @ev0 + 1 AS id, 'Teacher evaluation - first term' AS title, 'Please answer honestly. Your answers are anonymous: your teacher and your classmates do not see who wrote them. Rate from 1 (poor) to 5 (excellent).' AS instructions, (@day0 + INTERVAL -6 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS sent_at_utc, (@day0 + INTERVAL 8 DAY + INTERVAL 17 HOUR + INTERVAL 0 MINUTE) AS due_at_utc, @term AS term_id, @u_coord1 AS created_by_user_id, (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -6 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
) AS r WHERE @go = 1;

INSERT INTO evaluation_questions (id, evaluation_id, position, text, kind, category, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @eq0 + 1 AS id, @ev0 + 1 AS evaluation_id, 1 AS position, 'The teacher explains the lessons clearly.' AS text, 'Rating' AS kind, 'Teaching' AS category, (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @eq0 + 2, @ev0 + 1, 2, 'The teacher is prepared for every class.', 'Rating', 'Preparation', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 3, @ev0 + 1, 3, 'The teacher keeps the class orderly and respectful.', 'Rating', 'Classroom management', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 4, @ev0 + 1, 4, 'The teacher answers questions and gives feedback on time.', 'Rating', 'Communication', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 5, @ev0 + 1, 5, 'The activities and quizzes match what was taught.', 'Rating', 'Assessment', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 6, @ev0 + 1, 6, 'The teacher treats every student fairly.', 'Rating', 'Professionalism', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 7, @ev0 + 1, 7, 'What does your teacher do well?', 'Comment', 'Comments', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 8, @ev0 + 1, 8, 'What can your teacher do better?', 'Comment', 'Comments', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

